#define main archived_cli_main
#include "../softmax-fused-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <fstream>
#include <iostream>
#include <iomanip>
#define CHECK(x) do{cudaError_t e=(x);if(e!=cudaSuccess){std::cerr<<cudaGetErrorString(e)<<"\n";return 3;}}while(0)
template<class T>std::vector<T> rb(const std::string&p){std::ifstream f(p,std::ios::binary|std::ios::ate);auto n=f.tellg();f.seekg(0);std::vector<T>x(size_t(n)/sizeof(T));f.read((char*)x.data(),n);return x;}
struct F{int kind,b,h,q,c,n;float scale;std::vector<float>input;std::vector<uint8_t>mask;void*src,*dst;uint8_t*dm;};
template<class T>void setup(F&f){std::vector<T>x(f.n);for(int i=0;i<f.n;i++)x[i]=T(f.input[i]);cudaMalloc(&f.src,f.n*2);cudaMalloc(&f.dst,(f.n+17)*2);cudaMemcpy(f.src,x.data(),f.n*2,cudaMemcpyHostToDevice);}
template<class T>void reset(F&f){std::vector<T>x(f.n+17,T(-8));cudaMemcpy(f.dst,x.data(),x.size()*2,cudaMemcpyHostToDevice);}
template<class T>void launch(F&f,int pad){scaled_masked_softmax_forward<T,T,float>((T*)f.dst,(T*)f.src,f.dm,f.scale,f.q,f.c,f.b,f.h,pad);}
template<class T>void collect(F&f,int pad,std::vector<float>&got,double&ce){std::vector<T>y(f.n+17),x(f.n),ref(f.n);for(int i=0;i<f.n;i++)x[i]=T(f.input[i]);cudaMemcpy(y.data(),f.dst,y.size()*2,cudaMemcpyDeviceToHost);reference<T,T,float>(ref.data(),x.data(),f.mask.data(),f.scale,pad,f.b,f.h,f.q,f.c);for(int i=0;i<f.n;i++)ce=std::max(ce,std::abs(double(float(y[i]))-float(ref[i])));for(auto a:y)got.push_back(float(a));}
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):20;std::string root=std::string(__FILE__).substr(0,std::string(__FILE__).find_last_of('/'));auto input=rb<float>(root+"/fixture.bin");auto gold=rb<double>(root+"/expected_outputs.bin");size_t pos=1;std::vector<F>fs;for(int ci=0;ci<int(input[0]);ci++){F f;f.kind=int(input[pos++]);f.b=int(input[pos++]);f.h=int(input[pos++]);f.q=int(input[pos++]);f.c=int(input[pos++]);f.scale=input[pos++];f.n=int(input[pos++]);f.input=std::vector<float>(input.begin()+pos,input.begin()+pos+f.n);pos+=f.n;for(int i=0;i<f.n;i++)f.mask.push_back(uint8_t(input[pos++]));if(f.kind==0)setup<Half>(f);else setup<BFloat16>(f);CHECK(cudaMalloc(&f.dm,f.n));CHECK(cudaMemcpy(f.dm,f.mask.data(),f.n,cudaMemcpyHostToDevice));fs.push_back(f);}for(auto&f:fs)for(int pad:{0,1}){if(f.kind==0)launch<Half>(f,pad);else launch<BFloat16>(f,pad);CHECK(cudaDeviceSynchronize());}
for(int trial=1;trial<=5;trial++){std::vector<double>times;std::vector<float>got;double ce=0;for(auto&f:fs)for(int pad:{0,1}){if(f.kind==0)reset<Half>(f);else reset<BFloat16>(f);CHECK(cudaDeviceSynchronize());auto st=std::chrono::steady_clock::now();for(int i=0;i<rep;i++){if(f.kind==0)launch<Half>(f,pad);else launch<BFloat16>(f,pad);}CHECK(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep);if(f.kind==0)collect<Half>(f,pad,got,ce);else collect<BFloat16>(f,pad,got,ce);}
bool ok=got.size()==gold.size();double ma=0,mr=0,sum=0;for(size_t i=0;i<got.size();i++){double e=std::abs(double(got[i])-gold[i]);ma=std::max(ma,e);mr=std::max(mr,e/std::max(std::abs(gold[i]),1e-12));ok &=std::isfinite(got[i])&&(gold[i]==-8?got[i]==-8:e<=1e-3);}ok &=ce<=1e-3;for(auto v:times)sum+=v;std::string file="output_trial"+std::to_string(trial)+".bin";std::ofstream out(file,std::ios::binary);out.write((char*)input.data(),input.size()*4);out.write((char*)got.data(),got.size()*4);out.close();std::cout<<std::setprecision(17)<<"STUDY_TRIAL {\"trial\":"<<trial<<",\"time_seconds\":"<<sum<<",\"correct\":"<<(ok?"true":"false")<<",\"checked_values\":"<<got.size()<<",\"max_abs_error\":"<<ma<<",\"max_rel_error\":"<<mr<<",\"source_CPU_max_abs_error\":"<<ce<<",\"timing_region\":\"sum16_scaledmasked_FP16_BF16_paths\",\"jit_excluded\":true,\"internal_repeats\":"<<rep<<",\"per_path_times_seconds\":[";for(size_t i=0;i<times.size();i++){if(i)std::cout<<",";std::cout<<times[i];}std::cout<<"],\"output_artifact\":{\"path\":\""<<file<<"\",\"dtype\":\"float32\",\"count\":"<<input.size()+got.size()<<",\"byte_order\":\"little\"}}\n";}}
